/** Every command rejects with a CmdError; anything else (IPC failure) is wrapped into one. */
export function toCmdError(e: unknown): CmdError {
  if (e && typeof e === "object" && "kind" in e && "message" in e) {
    const { kind, message } = e as { kind: unknown; message: unknown };
    return { kind: String(kind), message: String(message) };
  }
  return { kind: "internal", message: e instanceof Error ? e.message : String(e) };
}

async function call<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  try {
    return await invoke<T>(cmd, args);
  } catch (e) {
    throw toCmdError(e);
  }
}

export const api = {
  appInfo: () => call<AppInfo>("app_info"),
  library: () => call<LibraryEntryDto[]>("library"),
  recents: () => call<RecentDto[]>("recents"),
  categories: () => call<CategoryDto[]>("categories"),
  categoryCreate: (name: string) => call<number | null>("category_create", { name }),
  categoryRename: (id: number, name: string) => call<void>("category_rename", { id, name }),
  categoryDelete: (id: number) => call<void>("category_delete", { id }),
  categoryMove: (id: number, up: boolean) => call<void>("category_move", { id, up }),
  mangaSetCategories: (mangaId: number, ids: number[]) =>
    call<void>("manga_set_categories", { mangaId, ids }),
  mangaDetail: (id: number) => call<MangaDetailDto>("manga_detail", { id }),
  rescanLocal: () => call<ImportResultDto>("rescan_local"),
  setViewer: (mangaId: number, viewer: number) => call<void>("set_viewer", { mangaId, viewer }),
  chapterPages: (chapterId: number) => call<ChapterPagesDto>("chapter_pages", { chapterId }),
  saveProgress: (chapterId: number, page: number, total: number) =>
    call<void>("save_progress", { chapterId, page, total }),
  setChapterRead: (chapterId: number, read: boolean) =>
    call<void>("set_chapter_read", { chapterId, read }),
  settingsGet: () => call<UiSettings>("settings_get"),
  settingsSet: (patch: UiSettingsPatch) => call<UiSettings>("settings_set", { patch }),
  cacheUsage: () => call<CacheUsageDto>("cache_usage"),
  cacheClear: () => call<CacheUsageDto>("cache_clear"),

  // Online sources. Source ids are strings (64-bit, beyond JS number precision).
  browseStatus: () => call<BrowseStatusDto>("browse_status"),
  extRepos: () => call<RepoDto[]>("ext_repos"),
  extRepoAdd: (url: string) => call<RepoDto>("ext_repo_add", { url }),
  extRepoRemove: (baseUrl: string) => call<void>("ext_repo_remove", { baseUrl }),
  extInstalled: () => call<InstalledExtensionDto[]>("ext_installed"),
  extCatalog: () => call<CatalogDto>("ext_catalog"),
  extInstall: (repoUrl: string, pkgName: string) => call<InstalledExtensionDto>("ext_install", { repoUrl, pkgName }),
  extUninstall: (pkgName: string) => call<void>("ext_uninstall", { pkgName }),
  browseSources: () => call<SourceDto[]>("browse_sources"),
  browseList: (sourceId: string, mode: BrowseMode, query: string | null, page: number) =>
    call<BrowsePageDto>("browse_list", { sourceId, mode, query, page }),
  onlineOpen: (sourceId: string, url: string, title: string) => call<RefreshDto>("online_open", { sourceId, url, title }),
  mangaRefresh: (id: number) => call<RefreshDto>("manga_refresh", { id }),
  /** Starts refreshing every online library title; progress arrives as `library-update` events. */
  libraryUpdate: () => call<number>("library_update"),
  librarySetFavorite: (id: number, favorite: boolean) => call<MangaDto>("library_set_favorite", { id, favorite }),
  sourcePreferences: (sourceId: string) => call<PreferenceDto[]>("source_preferences", { sourceId }),
  sourcePreferenceSet: (sourceId: string, key: string, value: unknown) =>
    call<PreferenceDto>("source_preference_set", { sourceId, key, value }),

  // Downloads. Queue changes arrive as `downloads` events.
  downloadsList: () => call<DownloadJobDto[]>("downloads_list"),
  downloadChapters: (mangaId: number, chapterIds: number[]) => call<number>("download_chapters", { mangaId, chapterIds }),
  downloadUnread: (mangaId: number) => call<number>("download_unread", { mangaId }),
  downloadDelete: (mangaId: number, chapterIds: number[]) => call<number>("download_delete", { mangaId, chapterIds }),
  downloadDismiss: (id: number) => call<void>("download_dismiss", { id }),
  downloadsClearFinished: () => call<void>("downloads_clear_finished"),
  downloadsOnDisk: () => call<DownloadedChapterDto[]>("downloads_on_disk"),

  // NAS storage. Upload changes arrive as `uploads` events.
  nasSettingsGet: () => call<NasSettingsDto>("nas_settings_get"),
  nasSettingsSet: (patch: NasSettingsPatch) => call<NasSettingsDto>("nas_settings_set", { patch }),
  /** Tries `patch` over the saved settings without saving; resolves with a short success line. */
  nasTest: (patch: NasSettingsPatch) => call<string>("nas_test", { patch }),
  nasUploads: () => call<UploadJobDto[]>("nas_uploads"),
  nasUploadsRetry: () => call<void>("nas_uploads_retry"),
  nasUploadDismiss: (id: number) => call<void>("nas_upload_dismiss", { id }),
  nasUploadsClearFinished: () => call<void>("nas_uploads_clear_finished"),
  nasCacheUsage: () => call<number>("nas_cache_usage"),
  nasCacheClear: () => call<number>("nas_cache_clear"),
  /** Lists the manga's NAS folder if it has not been listed yet; true when it was. */
  nasListManga: (id: number) => call<boolean>("nas_list_manga", { id }),

  // LAN sync and backup files. Status changes arrive as `sync` events.
  syncStatus: () => call<SyncStatusDto>("sync_status"),
  syncAddPeer: (host: string, port: number) => call<PeerDto>("sync_add_peer", { host, port }),
  syncPull: (peerId: string, code: string) => call<PullReportDto>("sync_pull", { peerId, code }),
  /** Opens a save dialog; resolves with the saved path, or null when cancelled. */
  backupExport: () => call<string | null>("backup_export"),
  /** Opens a file dialog; resolves with what was restored, or null when cancelled. */
  backupRestore: () => call<RestoreDto | null>("backup_restore"),
  /** The extensions the last restore can install, matched against the user's repos. */
  restoreExtensions: () => call<RestoreExtensionsDto>("restore_extensions"),
  /** Queues the chapters the backup's device had downloaded; resolves with how many. */
  restoreRedownload: (unreadOnly: boolean) => call<number>("restore_redownload", { unreadOnly }),
  restoreDismiss: () => call<void>("restore_dismiss"),

  // AniList. Account changes arrive as `anilist` events; a push after reading as `track-changed`.
  anilistAccount: () => call<AniListAccountDto>("anilist_account"),
  /** Opens the browser and waits (up to 5 minutes) for AniList to send the user back. */
  anilistConnect: () => call<AniListAccountDto>("anilist_connect"),
  anilistConnectToken: (token: string) => call<AniListAccountDto>("anilist_connect_token", { token }),
  anilistDisconnect: () => call<AniListAccountDto>("anilist_disconnect"),
  trackGet: (mangaId: number) => call<TrackDto | null>("track_get", { mangaId }),
  trackSearch: (query: string) => call<MediaDto[]>("track_search", { query }),
  trackBind: (mangaId: number, media: MediaDto) => call<TrackDto>("track_bind", { mangaId, media }),
  trackUnbind: (mangaId: number) => call<void>("track_unbind", { mangaId }),
  trackSetStatus: (mangaId: number, status: number) => call<TrackDto>("track_set_status", { mangaId, status }),
  trackSetProgress: (mangaId: number, progress: number) => call<TrackDto>("track_set_progress", { mangaId, progress }),
  trackSetScore: (mangaId: number, score: number) => call<TrackDto>("track_set_score", { mangaId, score }),
  trackOpen: (mangaId: number) => call<void>("track_open", { mangaId }),

  // Updates. Progress and results also arrive as `update` events.
  updateStatus: () => call<UpdateStatusDto>("update_status"),
  updateCheck: () => call<UpdateStatusDto>("update_check"),
  updateDownload: () => call<UpdateStatusDto>("update_download"),
  /** Runs the downloaded installer; the app quits so it can be replaced. */
  updateInstall: () => call<void>("update_install"),
  updateOpenPage: () => call<void>("update_open_page"),

  // The extension helper (ext-host and its Java), installed into the data folder.
  helperStatus: () => call<HelperStatusDto>("helper_status"),
  /** Opens a file dialog; null when cancelled. */
  helperInstallFile: () => call<HelperStatusDto | null>("helper_install_file"),
  helperDownload: () => call<HelperStatusDto>("helper_download"),
};

export type { LibraryUpdateDto };
export type BrowseMode = "popular" | "latest" | "search";
